// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { PopoverProps } from "./popover.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";
import { boxShadowToDropShadow } from "@theme/utils/css-transforms";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Popover";

// Generate child element class names for the component, should match available style slots
export const PopoverClasses = {
  root: "exp-textura_popover",
  content: "exp-textura_popover_content",
  divider: "exp-textura_popover_divider",
  footerButton: "exp-textura_popover_footer_button",
  triggerWrapper: "exp-textura_popover_trigger_wrapper",
  arrow: "exp-textura_popover_arrow",
  arrowTop: "exp-textura_popover_arrow_top",
  arrowBottom: "exp-textura_popover_arrow_bottom",
  arrowLeft: "exp-textura_popover_arrow_left",
  arrowRight: "exp-textura_popover_arrow_right",
};

const generateStyles = (props: PopoverProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<PopoverProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    borderRadius: theme.toRem(theme.popover.border.radius),
    filter: boxShadowToDropShadow(theme.dropShadow.lg, theme),
    maxWidth: theme.toRem(320),
    backgroundColor: theme.popover.color.background,
    color: theme.popover.color.content,
    padding: theme.toRem(theme.spacing[16]),
    ...theme.typography.body.md,

    [`&.${PopoverClasses.triggerWrapper}`]: {
      all: "unset",
      display: "flex",
      pointerEvents: "auto",
      cursor: "pointer",
      ...styleSlots?.triggerWrapper,
    },

    [`.${PopoverClasses.content}`]: {
      display: "flex",
      alignItems: "center",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[8]),
      ...styleSlots?.content,
    },

    [`.${PopoverClasses.arrow}`]: {
      strokeWidth: 1,
      fill: theme.popover.color.background,
      // Fixes a visual artifact where a small line can be seen between the arrow and the popover
      transform: "translateY(-1px)",
      "& > path": {
        stroke: theme.popover.color.background,
        strokeDashoffset: -147,
        strokeDasharray: 67,
        strokeWidth: theme.toRem("0.5px"),
        ...styleSlots?.arrowPath,
      },
      ...styleSlots?.arrow,
    },

    [`.${PopoverClasses.arrowTop}`]: {
      top: "calc(100% - 1px) !important",
      ...styleSlots?.arrowTop,
    },

    [`.${PopoverClasses.arrowBottom}`]: {
      bottom: "calc(100% - 1px) !important",
      ...styleSlots?.arrowBottom,
    },

    [`.${PopoverClasses.arrowLeft}`]: {
      insetInlineStart: "calc(100% - 1px) !important",
      ...styleSlots?.arrowLeft,
    },

    [`.${PopoverClasses.arrowRight}`]: {
      insetInlineEnd: "calc(100% - 1px) !important",
      ...styleSlots?.arrowRight,
    },

    [`.${PopoverClasses.divider}`]: {
      width: "fill-available !important",
      margin: `calc(${theme.toRem(theme.spacing[16])} * -1)`,
      marginTop: theme.toRem(theme.spacing[8]),
      marginBottom: `calc(${theme.toRem(theme.spacing[8])} * -1)`,
      ...styleSlots?.divider,
    },

    [`.${PopoverClasses.footerButton}`]: {
      padding: 0,
      width: "fill-available",
      margin: `calc(${theme.toRem(theme.spacing[16])} * -1)`,
      marginTop: 0,
      display: "flex",
      justifyContent: "center",
      borderTop: `${theme.toRem(theme.divider.default.border.width)} solid ${theme.divider.default.color.default}`,
      borderRadius: 0,
      flexGrow: 1,
      ...styleSlots?.footerButton,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledPopover = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<PopoverProps>((props) => generateStyles(props));
